-- Initial SQLite baseline for the original BidLens application.
CREATE TABLE "UserProfile" ("id" TEXT NOT NULL PRIMARY KEY, "email" TEXT NOT NULL, "displayName" TEXT, "createdAt" DATETIME NOT NULL, "updatedAt" DATETIME NOT NULL);
CREATE UNIQUE INDEX "UserProfile_email_key" ON "UserProfile"("email");
CREATE TABLE "UserSettings" ("id" TEXT NOT NULL PRIMARY KEY, "userId" TEXT NOT NULL, "preferredCurrency" TEXT NOT NULL DEFAULT 'USD', "defaultTaxRate" INTEGER NOT NULL DEFAULT 750, "defaultBuyerPremiumPercent" INTEGER NOT NULL DEFAULT 1800, "defaultSellingFeePercent" INTEGER NOT NULL DEFAULT 1300, "defaultPaymentFeePercent" INTEGER NOT NULL DEFAULT 300, "defaultOutboundShipping" INTEGER NOT NULL DEFAULT 1800, "defaultPackagingCost" INTEGER NOT NULL DEFAULT 300, "defaultCleaningAllowance" INTEGER NOT NULL DEFAULT 2000, "defaultRepairAllowance" INTEGER NOT NULL DEFAULT 0, "defaultAuthenticationAllowance" INTEGER NOT NULL DEFAULT 3500, "defaultReturnRiskPercent" INTEGER NOT NULL DEFAULT 500, "minimumRequiredProfit" INTEGER NOT NULL DEFAULT 10000, "minimumRequiredROI" INTEGER NOT NULL DEFAULT 3000, "buyThresholdScore" INTEGER NOT NULL DEFAULT 72, "reviewThresholdScore" INTEGER NOT NULL DEFAULT 45, "preferredMarketplaces" TEXT NOT NULL DEFAULT '["eBay"]', "timezone" TEXT NOT NULL DEFAULT 'America/New_York', "demoMode" BOOLEAN NOT NULL DEFAULT true, "updatedAt" DATETIME NOT NULL);
CREATE UNIQUE INDEX "UserSettings_userId_key" ON "UserSettings"("userId");
CREATE TABLE "AuctionListing" ("id" TEXT NOT NULL PRIMARY KEY, "userId" TEXT NOT NULL, "sourcePlatform" TEXT NOT NULL DEFAULT 'EBTH', "sourceUrl" TEXT, "sourceListingId" TEXT, "title" TEXT NOT NULL, "description" TEXT NOT NULL DEFAULT '', "category" TEXT NOT NULL, "originalCategory" TEXT, "currentBid" INTEGER NOT NULL, "currency" TEXT NOT NULL DEFAULT 'USD', "buyerPremiumType" TEXT NOT NULL DEFAULT 'PERCENT', "buyerPremiumValue" INTEGER NOT NULL, "taxRate" INTEGER NOT NULL, "inboundShippingCost" INTEGER NOT NULL DEFAULT 0, "pickupCost" INTEGER NOT NULL DEFAULT 0, "auctionEndAt" DATETIME, "bidCount" INTEGER, "locationText" TEXT, "conditionText" TEXT, "ingestionMethod" TEXT NOT NULL, "ingestionStatus" TEXT NOT NULL, "lastRefreshedAt" DATETIME, "createdAt" DATETIME NOT NULL, "updatedAt" DATETIME NOT NULL);
CREATE TABLE "ListingImage" ("id" TEXT NOT NULL PRIMARY KEY, "auctionListingId" TEXT NOT NULL, "storagePath" TEXT NOT NULL, "originalUrl" TEXT, "displayOrder" INTEGER NOT NULL, "imageType" TEXT NOT NULL, "isPrimary" BOOLEAN NOT NULL DEFAULT false, "width" INTEGER, "height" INTEGER, "createdAt" DATETIME NOT NULL);
CREATE TABLE "ProductAnalysis" ("id" TEXT NOT NULL PRIMARY KEY, "auctionListingId" TEXT NOT NULL, "provider" TEXT NOT NULL, "providerModel" TEXT NOT NULL, "status" TEXT NOT NULL, "rawStructuredResult" TEXT NOT NULL, "category" TEXT NOT NULL, "brand" TEXT, "suspectedModel" TEXT, "productLine" TEXT, "styleNumber" TEXT, "serialOrDateCode" TEXT, "color" TEXT NOT NULL, "material" TEXT NOT NULL, "size" TEXT, "dimensions" TEXT, "estimatedEra" TEXT, "genderMarket" TEXT, "conditionGrade" TEXT NOT NULL, "identificationConfidence" REAL NOT NULL, "authenticityRiskLevel" TEXT NOT NULL, "authenticityConfidence" REAL, "visibleDamage" TEXT NOT NULL, "includedItems" TEXT NOT NULL, "evidence" TEXT NOT NULL, "conflictingEvidence" TEXT NOT NULL, "searchQueries" TEXT NOT NULL, "createdAt" DATETIME NOT NULL, "updatedAt" DATETIME NOT NULL);
CREATE TABLE "ProductCandidate" ("id" TEXT NOT NULL PRIMARY KEY, "productAnalysisId" TEXT NOT NULL, "rank" INTEGER NOT NULL, "brand" TEXT, "model" TEXT, "productLine" TEXT, "category" TEXT NOT NULL, "color" TEXT NOT NULL, "material" TEXT NOT NULL, "size" TEXT, "estimatedEra" TEXT, "confidence" REAL NOT NULL, "evidence" TEXT NOT NULL, "conflictingEvidence" TEXT NOT NULL, "searchQueries" TEXT NOT NULL, "isSelected" BOOLEAN NOT NULL DEFAULT false, "createdAt" DATETIME NOT NULL);
CREATE TABLE "Comparable" ("id" TEXT NOT NULL PRIMARY KEY, "userId" TEXT NOT NULL, "auctionListingId" TEXT NOT NULL, "provider" TEXT NOT NULL, "externalId" TEXT, "sourceUrl" TEXT, "title" TEXT NOT NULL, "imageUrl" TEXT, "marketplace" TEXT NOT NULL, "comparableStatus" TEXT NOT NULL, "price" INTEGER NOT NULL, "shippingPrice" INTEGER NOT NULL, "currency" TEXT NOT NULL, "totalPrice" INTEGER NOT NULL, "condition" TEXT, "size" TEXT, "color" TEXT, "material" TEXT, "includedItems" TEXT, "soldOrListedAt" DATETIME, "similarityScore" INTEGER NOT NULL, "dataQualityScore" INTEGER NOT NULL, "userIncluded" BOOLEAN NOT NULL DEFAULT true, "exclusionReason" TEXT, "userNotes" TEXT, "rawSourceData" TEXT, "createdAt" DATETIME NOT NULL, "updatedAt" DATETIME NOT NULL);
CREATE TABLE "Valuation" ("id" TEXT NOT NULL PRIMARY KEY, "auctionListingId" TEXT NOT NULL, "methodVersion" TEXT NOT NULL, "quickSaleEstimate" INTEGER NOT NULL, "expectedResaleValue" INTEGER NOT NULL, "optimisticResaleValue" INTEGER NOT NULL, "lowEstimate" INTEGER NOT NULL, "highEstimate" INTEGER NOT NULL, "valuationConfidence" INTEGER NOT NULL, "comparableCount" INTEGER NOT NULL, "verifiedSoldComparableCount" INTEGER NOT NULL, "activeComparableCount" INTEGER NOT NULL, "rationale" TEXT NOT NULL, "calculatedAt" DATETIME NOT NULL);
CREATE TABLE "BidRecommendation" ("id" TEXT NOT NULL PRIMARY KEY, "auctionListingId" TEXT NOT NULL, "valuationId" TEXT NOT NULL, "currentHammerBid" INTEGER NOT NULL, "buyerPremiumAmount" INTEGER NOT NULL, "salesTaxAmount" INTEGER NOT NULL, "inboundShipping" INTEGER NOT NULL, "pickupCost" INTEGER NOT NULL, "authenticationAllowance" INTEGER NOT NULL, "cleaningAllowance" INTEGER NOT NULL, "repairAllowance" INTEGER NOT NULL, "otherAcquisitionCosts" INTEGER NOT NULL, "expectedResaleValue" INTEGER NOT NULL, "sellingFees" INTEGER NOT NULL, "paymentFees" INTEGER NOT NULL, "outboundShipping" INTEGER NOT NULL, "packagingCost" INTEGER NOT NULL, "returnRiskReserve" INTEGER NOT NULL, "otherSellingCosts" INTEGER NOT NULL, "minimumRequiredProfit" INTEGER NOT NULL, "maximumAllInAcquisitionCost" INTEGER NOT NULL, "maximumRecommendedHammerBid" INTEGER NOT NULL, "expectedNetProfitAtCurrentBid" INTEGER NOT NULL, "expectedROIAtCurrentBid" INTEGER, "opportunityScore" INTEGER NOT NULL, "recommendation" TEXT NOT NULL, "warnings" TEXT NOT NULL, "calculatedAt" DATETIME NOT NULL);
CREATE TABLE "WatchlistItem" ("id" TEXT NOT NULL PRIMARY KEY, "userId" TEXT NOT NULL, "auctionListingId" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'ACTIVE', "alertEnabled" BOOLEAN NOT NULL DEFAULT true, "userMaximumBid" INTEGER, "notes" TEXT, "createdAt" DATETIME NOT NULL, "updatedAt" DATETIME NOT NULL);
CREATE UNIQUE INDEX "WatchlistItem_auctionListingId_key" ON "WatchlistItem"("auctionListingId");
CREATE TABLE "AuctionOutcome" ("id" TEXT NOT NULL PRIMARY KEY, "userId" TEXT NOT NULL, "auctionListingId" TEXT NOT NULL, "outcome" TEXT NOT NULL, "finalHammerPrice" INTEGER, "finalBuyerPremium" INTEGER, "finalTax" INTEGER, "finalInboundShipping" INTEGER, "finalPickupCost" INTEGER, "authenticationCost" INTEGER, "cleaningCost" INTEGER, "repairCost" INTEGER, "otherCost" INTEGER, "acquiredAt" DATETIME, "notes" TEXT, "createdAt" DATETIME NOT NULL, "updatedAt" DATETIME NOT NULL);
CREATE TABLE "ResaleOutcome" ("id" TEXT NOT NULL PRIMARY KEY, "userId" TEXT NOT NULL, "auctionListingId" TEXT NOT NULL, "marketplace" TEXT NOT NULL, "listedAt" DATETIME, "soldAt" DATETIME, "listingPrice" INTEGER, "salePrice" INTEGER, "marketplaceFees" INTEGER, "paymentFees" INTEGER, "promotionalFees" INTEGER, "shippingChargedToBuyer" INTEGER, "outboundShippingCost" INTEGER, "packagingCost" INTEGER, "refundAmount" INTEGER, "otherCosts" INTEGER, "returned" BOOLEAN NOT NULL DEFAULT false, "netRealizedProfit" INTEGER, "realizedROI" INTEGER, "daysToSell" INTEGER, "predictionErrorAmount" INTEGER, "predictionErrorPercent" INTEGER, "notes" TEXT, "createdAt" DATETIME NOT NULL, "updatedAt" DATETIME NOT NULL);
CREATE TABLE "Alert" ("id" TEXT NOT NULL PRIMARY KEY, "userId" TEXT NOT NULL, "auctionListingId" TEXT NOT NULL, "alertType" TEXT NOT NULL, "thresholdValue" INTEGER, "message" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'UNREAD', "triggeredAt" DATETIME, "readAt" DATETIME, "createdAt" DATETIME NOT NULL);
CREATE TABLE "AuditLog" ("id" TEXT NOT NULL PRIMARY KEY, "userId" TEXT NOT NULL, "action" TEXT NOT NULL, "entityType" TEXT NOT NULL, "entityId" TEXT, "metadata" TEXT, "createdAt" DATETIME NOT NULL);
CREATE TABLE "ProviderCache" ("id" TEXT NOT NULL PRIMARY KEY, "cacheKey" TEXT NOT NULL, "provider" TEXT NOT NULL, "payload" TEXT NOT NULL, "expiresAt" DATETIME NOT NULL, "createdAt" DATETIME NOT NULL);
CREATE UNIQUE INDEX "ProviderCache_cacheKey_key" ON "ProviderCache"("cacheKey");
CREATE TABLE "Job" ("id" TEXT NOT NULL PRIMARY KEY, "userId" TEXT NOT NULL, "type" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'QUEUED', "payload" TEXT NOT NULL, "error" TEXT, "createdAt" DATETIME NOT NULL, "updatedAt" DATETIME NOT NULL);
CREATE TABLE "ListingFinancialAssumptions" ("id" TEXT NOT NULL PRIMARY KEY, "auctionListingId" TEXT NOT NULL, "taxHammer" BOOLEAN NOT NULL DEFAULT true, "taxPremium" BOOLEAN NOT NULL DEFAULT true, "authentication" INTEGER NOT NULL DEFAULT 0, "cleaning" INTEGER NOT NULL DEFAULT 0, "repair" INTEGER NOT NULL DEFAULT 0, "otherAcquisition" INTEGER NOT NULL DEFAULT 0, "sellingFeeBps" INTEGER NOT NULL DEFAULT 1300, "paymentFeeBps" INTEGER NOT NULL DEFAULT 300, "promotional" INTEGER NOT NULL DEFAULT 0, "outbound" INTEGER NOT NULL DEFAULT 0, "packaging" INTEGER NOT NULL DEFAULT 0, "returnRiskBps" INTEGER NOT NULL DEFAULT 500, "otherSelling" INTEGER NOT NULL DEFAULT 0, "minimumProfit" INTEGER NOT NULL DEFAULT 10000, "minimumRoiBps" INTEGER NOT NULL DEFAULT 3000, "bidIncrement" INTEGER NOT NULL DEFAULT 500, "notes" TEXT, "updatedAt" DATETIME NOT NULL);
CREATE UNIQUE INDEX "ListingFinancialAssumptions_auctionListingId_key" ON "ListingFinancialAssumptions"("auctionListingId");
CREATE UNIQUE INDEX "ProductCandidate_productAnalysisId_rank_key" ON "ProductCandidate"("productAnalysisId","rank");
CREATE UNIQUE INDEX "Comparable_provider_externalId_key" ON "Comparable"("provider","externalId");
